40	std::future<IAsynchronousReader::Result> AsynchronousReadBufferFromFileDescriptor::asyncReadInto(char * data, size_t size)
41	{
42	    IAsynchronousReader::Request request;
43	    request.descriptor = std::make_shared<IAsynchronousReader::LocalFileDescriptor>(fd);
44	    request.buf = data;
45	    request.size = size;
46	    request.offset = file_offset_of_buffer_end;
47	    request.priority = priority;
48	    request.ignore = bytes_to_ignore;
49	    bytes_to_ignore = 0;
50	
51	    /// This is a workaround of a read pass EOF bug in linux kernel with pread()
52	    if (file_size.has_value() && file_offset_of_buffer_end >= *file_size)
53	    {
54	        return std::async(std::launch::deferred, [] { return IAsynchronousReader::Result{.size = 0, .offset = 0}; });
55	    }
56	
57	    return reader->submit(request);
58	}
