61	void AsynchronousReadBufferFromFileDescriptor::prefetch()
62	{
63	    if (prefetch_future.valid())
64	        return;
65	
66	    /// Will request the same amount of data that is read in nextImpl.
67	    prefetch_buffer.resize(internal_buffer.size());
68	    prefetch_future = asyncReadInto(prefetch_buffer.data(), prefetch_buffer.size());
69	}
