72	bool AsynchronousReadBufferFromFileDescriptor::nextImpl()
73	{
74	    if (prefetch_future.valid())
75	    {
76	        /// Read request already in flight. Wait for its completion.
77	
78	        size_t size = 0;
79	        size_t offset = 0;
80	        {
81	            Stopwatch watch;
82	            CurrentMetrics::Increment metric_increment{CurrentMetrics::AsynchronousReadWait};
83	            auto result = prefetch_future.get();
84	            size = result.size;
85	            offset = result.offset;
86	            assert(offset < size || size == 0);
87	            ProfileEvents::increment(ProfileEvents::AsynchronousReadWaitMicroseconds, watch.elapsedMicroseconds());
88	        }
89	
90	        prefetch_future = {};
91	        file_offset_of_buffer_end += size;
92	
93	        if (size)
94	        {
95	            prefetch_buffer.swap(memory);
96	            /// Adjust the working buffer so that it ignores `offset` bytes.
97	            internal_buffer = Buffer(memory.data(), memory.data() + memory.size());
98	            working_buffer = Buffer(memory.data() + offset, memory.data() + size);
99	            pos = working_buffer.begin();
100	            return true;
101	        }
102	
103	        return false;
104	    }
105	    else
106	    {
107	        /// No pending request. Do synchronous read.
108	
109	        auto [size, offset] = asyncReadInto(memory.data(), memory.size()).get();
110	        file_offset_of_buffer_end += size;
111	
112	        if (size)
113	        {
114	            /// Adjust the working buffer so that it ignores `offset` bytes.
115	            internal_buffer = Buffer(memory.data(), memory.data() + memory.size());
116	            working_buffer = Buffer(memory.data() + offset, memory.data() + size);
117	            pos = working_buffer.begin();
118	            return true;
119	        }
120	
121	        return false;
122	    }
123	}
