166	/// If 'offset' is small enough to stay in buffer after seek, then true seek in file does not happen.
167	off_t AsynchronousReadBufferFromFileDescriptor::seek(off_t offset, int whence)
168	{
169	    size_t new_pos;
170	    if (whence == SEEK_SET)
171	    {
172	        assert(offset >= 0);
173	        new_pos = offset;
174	    }
175	    else if (whence == SEEK_CUR)
176	    {
177	        new_pos = file_offset_of_buffer_end - (working_buffer.end() - pos) + offset;
178	    }
179	    else
180	    {
181	        throw Exception("ReadBufferFromFileDescriptor::seek expects SEEK_SET or SEEK_CUR as whence", ErrorCodes::ARGUMENT_OUT_OF_BOUND);
182	    }
183	
184	    /// Position is unchanged.
185	    if (new_pos + (working_buffer.end() - pos) == file_offset_of_buffer_end)
186	        return new_pos;
187	
188	    while (true)
189	    {
190	        if (file_offset_of_buffer_end - working_buffer.size() <= new_pos && new_pos <= file_offset_of_buffer_end)
191	        {
192	            /// Position is still inside the buffer.
193	            /// Probably it is at the end of the buffer - then we will load data on the following 'next' call.
194	
195	            pos = working_buffer.end() - file_offset_of_buffer_end + new_pos;
196	            assert(pos >= working_buffer.begin());
197	            assert(pos <= working_buffer.end());
198	
199	            return new_pos;
200	        }
201	        else if (prefetch_future.valid())
202	        {
203	            /// Read from prefetch buffer and recheck if the new position is valid inside.
204	            if (nextImpl())
205	                continue;
206	        }
207	
208	        break;
209	    }
210	
211	    assert(!prefetch_future.valid());
212	
213	    /// Position is out of the buffer, we need to do real seek.
214	    off_t seek_pos = required_alignment > 1
215	        ? new_pos / required_alignment * required_alignment
216	        : new_pos;
217	
218	    /// First reset the buffer so the next read will fetch new data to the buffer.
219	    resetWorkingBuffer();
220	
221	    /// Just update the info about the next position in file.
222	
223	    file_offset_of_buffer_end = seek_pos;
224	    bytes_to_ignore = new_pos - seek_pos;
225	
226	    if (bytes_to_ignore >= internal_buffer.size())
227	        throw Exception(ErrorCodes::LOGICAL_ERROR, "Logical error in AsynchronousReadBufferFromFileDescriptor, bytes_to_ignore ({}) >= internal_buffer.size() ({})", bytes_to_ignore, internal_buffer.size());
228	
229	    return seek_pos;
230	}
