233	void AsynchronousReadBufferFromFileDescriptor::rewind()
234	{
235	    if (prefetch_future.valid())
236	    {
237	        prefetch_future.wait();
238	        prefetch_future = {};
239	    }
240	
241	    /// Clearing the buffer with existing data. New data will be read on subsequent call to 'next'.
242	    working_buffer.resize(0);
243	    pos = working_buffer.begin();
244	    file_offset_of_buffer_end = 0;
245	}
