75	bool AsynchronousReadIndirectBufferFromRemoteFS::hasPendingDataToRead()
76	{
77	    /**
78	     * Note: read_until_position here can be std::nullopt only for non-MergeTree tables.
79	     * For mergeTree tables it must be guaranteed that setReadUntilPosition() or
80	     * setReadUntilEnd() is called before any read or prefetch.
81	     * setReadUntilEnd() always sets read_until_position to file size.
82	     * setReadUntilPosition(pos) always has pos > 0, because if
83	     * right_offset_in_compressed_file is 0, then setReadUntilEnd() is used.
84	     */
85	    if (read_until_position)
86	    {
87	        /// Everything is already read.
88	        if (file_offset_of_buffer_end == *read_until_position)
89	            return false;
90	
91	        if (file_offset_of_buffer_end > *read_until_position)
92	            throw Exception(ErrorCodes::LOGICAL_ERROR, "Read beyond last offset ({} > {}, info: {})",
93	                            file_offset_of_buffer_end, *read_until_position, impl->getInfoForLog());
94	    }
95	
96	    return true;
97	}
