162	bool AsynchronousReadIndirectBufferFromRemoteFS::nextImpl()
163	{
164	    if (!hasPendingDataToRead())
165	        return false;
166	
167	    Stopwatch watch;
168	    CurrentMetrics::Increment metric_increment{CurrentMetrics::AsynchronousReadWait};
169	
170	    size_t size = 0;
171	    if (prefetch_future.valid())
172	    {
173	        ProfileEvents::increment(ProfileEvents::RemoteFSPrefetchedReads);
174	
175	        size_t offset = 0;
176	        {
177	            auto result = prefetch_future.get();
178	            size = result.size;
179	            offset = result.offset;
180	            LOG_TEST(log, "Current size: {}, offset: {}", size, offset);
181	
182	            /// If prefetch_future is valid, size should always be greater than zero.
183	            assert(offset <= size);
184	            ProfileEvents::increment(ProfileEvents::AsynchronousReadWaitMicroseconds, watch.elapsedMicroseconds());
185	        }
186	
187	        prefetch_buffer.swap(memory);
188	
189	        /// Adjust the working buffer so that it ignores `offset` bytes.
190	        internal_buffer = Buffer(memory.data(), memory.data() + memory.size());
191	        working_buffer = Buffer(memory.data() + offset, memory.data() + size);
192	        pos = working_buffer.begin();
193	    }
194	    else
195	    {
196	        ProfileEvents::increment(ProfileEvents::RemoteFSUnprefetchedReads);
197	
198	        auto result = asyncReadInto(memory.data(), memory.size()).get();
199	        size = result.size;
200	        auto offset = result.offset;
201	
202	        LOG_TEST(log, "Current size: {}, offset: {}", size, offset);
203	        assert(offset <= size);
204	
205	        if (size)
206	        {
207	            /// Adjust the working buffer so that it ignores `offset` bytes.
208	            internal_buffer = Buffer(memory.data(), memory.data() + memory.size());
209	            working_buffer = Buffer(memory.data() + offset, memory.data() + size);
210	            pos = working_buffer.begin();
211	        }
212	    }
213	
214	    watch.stop();
215	    ProfileEvents::increment(ProfileEvents::AsynchronousReadWaitMicroseconds, watch.elapsedMicroseconds());
216	
217	    file_offset_of_buffer_end = impl->getFileOffsetOfBufferEnd();
218	    /// In case of multiple files for the same file in clickhouse (i.e. log family)
219	    /// file_offset_of_buffer_end will not match getImplementationBufferOffset()
220	    /// so we use [impl->getImplementationBufferOffset(), impl->getFileSize()]
221	    assert(file_offset_of_buffer_end >= impl->getImplementationBufferOffset());
222	    assert(file_offset_of_buffer_end <= impl->getFileSize());
223	
224	    prefetch_future = {};
225	    return size;
226	}
