229	off_t AsynchronousReadIndirectBufferFromRemoteFS::seek(off_t offset, int whence)
230	{
231	    ProfileEvents::increment(ProfileEvents::RemoteFSSeeks);
232	
233	    size_t new_pos;
234	    if (whence == SEEK_SET)
235	    {
236	        assert(offset >= 0);
237	        new_pos = offset;
238	    }
239	    else if (whence == SEEK_CUR)
240	    {
241	        new_pos = file_offset_of_buffer_end - (working_buffer.end() - pos) + offset;
242	    }
243	    else
244	    {
245	        throw Exception("ReadBufferFromFileDescriptor::seek expects SEEK_SET or SEEK_CUR as whence", ErrorCodes::ARGUMENT_OUT_OF_BOUND);
246	    }
247	
248	    /// Position is unchanged.
249	    if (new_pos + (working_buffer.end() - pos) == file_offset_of_buffer_end)
250	        return new_pos;
251	
252	    bool read_from_prefetch = false;
253	    while (true)
254	    {
255	        if (file_offset_of_buffer_end - working_buffer.size() <= new_pos && new_pos <= file_offset_of_buffer_end)
256	        {
257	            /// Position is still inside the buffer.
258	            /// Probably it is at the end of the buffer - then we will load data on the following 'next' call.
259	
260	            pos = working_buffer.end() - file_offset_of_buffer_end + new_pos;
261	            assert(pos >= working_buffer.begin());
262	            assert(pos <= working_buffer.end());
263	
264	            return new_pos;
265	        }
266	        else if (prefetch_future.valid())
267	        {
268	            /// Read from prefetch buffer and recheck if the new position is valid inside.
269	
270	            if (nextImpl())
271	            {
272	                read_from_prefetch = true;
273	                continue;
274	            }
275	        }
276	
277	        /// Prefetch is cancelled because of seek.
278	        if (read_from_prefetch)
279	            ProfileEvents::increment(ProfileEvents::RemoteFSCancelledPrefetches);
280	
281	        break;
282	    }
283	
284	    assert(!prefetch_future.valid());
285	
286	    /// First reset the buffer so the next read will fetch new data to the buffer.
287	    resetWorkingBuffer();
288	
289	    /**
290	    * Lazy ignore. Save number of bytes to ignore and ignore it either for prefetch buffer or current buffer.
291	    * Note: we read in range [file_offset_of_buffer_end, read_until_position).
292	    */
293	    if (impl->initialized()
294	        && read_until_position && new_pos < *read_until_position
295	        && new_pos > file_offset_of_buffer_end
296	        && new_pos < file_offset_of_buffer_end + min_bytes_for_seek)
297	    {
298	        ProfileEvents::increment(ProfileEvents::RemoteFSLazySeeks);
299	        bytes_to_ignore = new_pos - file_offset_of_buffer_end;
300	    }
301	    else
302	    {
303	        ProfileEvents::increment(ProfileEvents::RemoteFSSeeksWithReset);
304	        impl->reset();
305	        file_offset_of_buffer_end = new_pos;
306	    }
307	
308	    return new_pos;
309	}
